contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public {
        uint256 beforeTotalDistributed = c.totalDistributed(); if (__ESBMC_reverted()) return;
        uint256 beforeBalance = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        require(amount <= beforeBalance);

        c.burn(amount); if (__ESBMC_reverted()) return;

        uint256 afterTotalDistributed = c.totalDistributed(); if (__ESBMC_reverted()) return;
        assert(afterTotalDistributed == beforeTotalDistributed - amount);
    }

    receive() external payable {}
}

